-- Indonesia has a few legacy exact-title duplicates from the priority and Bali
-- extended seeds. Updating all exact matches is safer than choosing one place
-- arbitrarily; only missing titles should block this overlay.
DO $$
BEGIN
    IF EXISTS (
        WITH candidate_matches AS (
            SELECT
                seed.title_ru,
                COUNT(DISTINCT p.id) AS match_count
            FROM seed_indonesia_visit_planning seed
            LEFT JOIN place_translations pt
              ON pt.locale = 'ru'
             AND pt.title = seed.title_ru
            LEFT JOIN places p
              ON p.id = pt.place_id
             AND p.country_code = 'ID'
             AND p.deleted_at IS NULL
             AND p.source = 'IMPORT'
            GROUP BY seed.title_ru
        )
        SELECT 1
        FROM candidate_matches
        WHERE match_count = 0
    ) THEN
        RAISE EXCEPTION 'Indonesia visit-planning seed has missing place matches';
    END IF;
END $$;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_indonesia_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'ID'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_fee_items f
USING matched_places m
WHERE f.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_indonesia_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'ID'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_access_options a
USING matched_places m
WHERE a.place_id = m.place_id;

